-- VoxAgent initial PostgreSQL schema. Apply through your migration runner in production.
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(32) NOT NULL DEFAULT 'agent', created_at TIMESTAMP NOT NULL DEFAULT NOW(), updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS contacts (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, phone VARCHAR(32) NOT NULL UNIQUE, email VARCHAR(255), company VARCHAR(120), notes TEXT, created_at TIMESTAMP NOT NULL DEFAULT NOW(), updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS calls (id SERIAL PRIMARY KEY, call_sid VARCHAR(100) NOT NULL UNIQUE, direction VARCHAR(16) NOT NULL, phone_number VARCHAR(32) NOT NULL, contact_id INTEGER REFERENCES contacts(id), status VARCHAR(32) NOT NULL DEFAULT 'queued', started_at TIMESTAMP, ended_at TIMESTAMP, duration INTEGER, recording_url VARCHAR(500), transcript TEXT, summary TEXT, sentiment VARCHAR(32), intent VARCHAR(64), created_at TIMESTAMP NOT NULL DEFAULT NOW(), updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS messages (id SERIAL PRIMARY KEY, call_id INTEGER NOT NULL REFERENCES calls(id) ON DELETE CASCADE, role VARCHAR(20) NOT NULL, content TEXT NOT NULL, timestamp TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS appointments (id SERIAL PRIMARY KEY, customer_name VARCHAR(120) NOT NULL, phone VARCHAR(32) NOT NULL, date VARCHAR(10) NOT NULL, time VARCHAR(8) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'booked', notes TEXT, created_at TIMESTAMP NOT NULL DEFAULT NOW(), updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS agents (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, system_prompt TEXT NOT NULL, voice VARCHAR(50) NOT NULL DEFAULT 'alloy', language VARCHAR(10) NOT NULL DEFAULT 'en', greeting TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT NOW(), updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS knowledge_documents (id SERIAL PRIMARY KEY, title VARCHAR(200) NOT NULL, content TEXT NOT NULL, category VARCHAR(80) NOT NULL DEFAULT 'general', created_at TIMESTAMP NOT NULL DEFAULT NOW(), updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_calls_status ON calls(status); CREATE INDEX IF NOT EXISTS idx_calls_phone ON calls(phone_number); CREATE INDEX IF NOT EXISTS idx_appointments_date ON appointments(date);
